import sys, json, random
sys.path.insert(0, 'tests')
import fuzz3, importlib.util
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
rng = random.Random(61)
def nodes(node):
    op = node['op']
    if op in ('true','false'): return 1
    if op == 'not': return 1 + nodes(node['arg'])
    if op in ('and','or'): return 1 + sum(nodes(a) for a in node['args'])
    return 1
for i in range(25):
    req = fuzz3.gen_request(rng)
    raw = json.dumps(req).encode()
    out = json.loads(m.process(raw))
    if out.get('ok') is not True:
        na = set()
        for r in req['rules']: fuzz3.count_atoms if False else None
        # count atoms
        def atoms(node, out_):
            op = node['op']
            if op in ('match','startswith','endswith','contains'): out_.add((op, tuple(node['path'])))
            elif op == 'not': atoms(node['arg'], out_)
            elif op in ('and','or'):
                for a in node['args']: atoms(a, out_)
        A = set()
        for r in req['rules']: atoms(r['when'], A)
        print(i, out, 'rules', len(req['rules']), 'nodes', sum(nodes(r['when']) for r in req['rules']), 'atoms', len(A), 'maxpath', max([len(p) for ps in A for p in [ps[1]]] or [0]), 'qtokens', sum(len(q) for q in req['queries']), 'maxargs', max(([len(r['when'].get('args', [])) for r in req['rules']] or [0])))
        if i > 3: break
